from pyspark.sql import SparkSession, functions as F
spark = SparkSession.builder.master("local[2]").getOrCreate()

import pandas as pd

df = spark.createDataFrame([("Ana Lopez",), ("ben ODA",), (None,)], "name STRING")

@F.udf(returnType="string", useArrow=True)        # Arrow-optimized Python UDF
def initials(s):
    return None if s is None else "".join(w[0].upper() for w in s.split())

@F.pandas_udf("int")                              # vectorized: whole Series at once
def name_len(s: pd.Series) -> pd.Series:
    return s.str.len().astype("Int32")

out = df.select("name", initials("name").alias("ini"), name_len("name").alias("n"))
print([tuple(r) for r in out.collect()])
# [('Ana Lopez', 'AL', 9), ('ben ODA', 'BO', 7), (None, None, None)]

# The built-in way: no Python at all, and fully optimized
print(df.select(F.length("name").alias("n")).first().n)   # 9
